#!/bin/bash
# Verifies the Rust -> Java interop direction: the Rust-serialized fixtures
# (tests/golden/rust_*.hex, regenerated by `cargo run --bin gen_golden`) are
# deserialized with the Java Message/Payload classes and asserted field-by-field.
set -e
JAVA_SRC="${JAVA_SRC:-/home/nicolas/Source/firebus}"
ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
OUT="$ROOT/target/golden-classes"
FIX="$ROOT/tests/golden"
mkdir -p "$OUT"
javac -d "$OUT" -sourcepath "$JAVA_SRC/FireBus/src/main/java:$JAVA_SRC/FirebusData/src/main/java" "$ROOT/tools/golden/VectorVerify.java"
java -cp "$OUT" VectorVerify "$FIX"
